    ('cb488596-151b-4cb8-903b-e93d24d5b53e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'So sánh là đối chiếu hai sự vật có nét tương đồng, ví dụ ''hiền như bụt''. Câu trên đúng hay sai?', 'So sanh la doi chieu hai su vat co net tuong dong, vi du ''hien nhu but''. Cau tren dung hay sai?', 'So sánh là đối chiếu hai sự vật có nét tương đồng, ví dụ ''hiền như bụt''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
