    ('bdfa6568-1421-4a9e-82cf-85f24a0b46cc', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nhân hóa là gọi hoặc tả con vật, đồ vật bằng từ ngữ vốn dùng cho người. Theo em, nhận định trên đúng hay sai?', 'Nhan hoa la goi hoac ta con vat, do vat bang tu ngu von dung cho nguoi. Theo em, nhan dinh tren dung hay sai?', 'Nhân hóa là gọi hoặc tả con vật, đồ vật bằng từ ngữ vốn dùng cho người.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
