    ('0a0e573a-40a4-40d9-8514-3de428c255b4', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Quê hương thường được miêu tả gắn với cánh đồng, dòng sông, lũy tre. Câu trên đúng hay sai?', 'Que huong thuong duoc mieu ta gan voi canh dong, dong song, luy tre. Cau tren dung hay sai?', 'Quê hương thường được miêu tả gắn với cánh đồng, dòng sông, lũy tre.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('c3b7a73f-c1fe-42bd-bb67-d60e31495b0a', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phương án nào dưới đây là đúng?', 'Phuong an nao duoi day la dung?', 'Kể chuyện cần có nhân vật, sự việc và diễn biến rõ ràng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('2875b665-d325-400e-a961-968f9b5a4249', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc. Theo em, nhận định trên đúng hay sai?', 'Tu ''xanh biec'' la mot tinh tu mieu ta mau sac. Theo em, nhan dinh tren dung hay sai?', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('f35543fa-9f93-4973-ac92-056b9aed0b1e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ý nào sau đây phản ánh đúng nội dung đã học?', 'Y nao sau day phan anh dung noi dung da hoc?', 'Dấu hai chấm thường dùng để báo hiệu lời giải thích hoặc liệt kê.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('09d2af23-3e2d-4f45-904c-9f770515e855', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Danh từ là từ chỉ hoạt động, trạng thái. Câu trên đúng hay sai?', 'Danh tu la tu chi hoat dong, trang thai. Cau tren dung hay sai?', 'Danh từ là từ chỉ người, sự vật, hiện tượng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('fe91aedc-4026-4c8e-9339-8214236f2ef0', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Xác định phát biểu đúng trong số các phương án sau:', 'Xac dinh phat bieu dung trong so cac phuong an sau:', 'Động từ là từ chỉ hoạt động, trạng thái của sự vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('5594a510-1837-42d0-8624-b01e0801ea87', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Tính từ là từ chỉ số lượng sự vật. Theo em, nhận định trên đúng hay sai?', 'Tinh tu la tu chi so luong su vat. Theo em, nhan dinh tren dung hay sai?', 'Tính từ là từ chỉ đặc điểm, tính chất của sự vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('25b17e00-62ae-4082-8415-f9fdeb6190b0', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu nào sau đây nêu đúng kiến thức đã học?', 'Cau nao sau day neu dung kien thuc da hoc?', 'So sánh là đối chiếu hai sự vật có nét tương đồng, ví dụ ''hiền như bụt''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
