    ('9e39a003-763b-48e1-8093-bbdfe2cc30f5', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc. Theo em, nhận định trên đúng hay sai?', 'Tu ''xanh biec'' la mot tinh tu mieu ta mau sac. Theo em, nhan dinh tren dung hay sai?', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
