    ('22c07f9d-d359-4eaf-8e20-32fcdb4885fe', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phát biểu nào dưới đây phù hợp với kiến thức đã học?', 'Phat bieu nao duoi day phu hop voi kien thuc da hoc?', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('a73ae200-9258-44f6-944b-54f15f530855', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Dấu hai chấm thường dùng để báo hiệu lời giải thích hoặc liệt kê. Câu trên đúng hay sai?', 'Dau hai cham thuong dung de bao hieu loi giai thich hoac liet ke. Cau tren dung hay sai?', 'Dấu hai chấm thường dùng để báo hiệu lời giải thích hoặc liệt kê.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('e090ed68-c012-4891-bc75-cab67ddb731f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy viết một đoạn văn ngắn (4-5 câu) tả một đồ vật em yêu thích.', 'Em hay viet mot doan van ngan (4-5 cau) ta mot do vat em yeu thich.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('f4fa54bd-b216-45a9-b7ca-94a52611d4c8', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Danh từ là từ chỉ người, sự vật, hiện tượng. Theo em, nhận định trên đúng hay sai?', 'Danh tu la tu chi nguoi, su vat, hien tuong. Theo em, nhan dinh tren dung hay sai?', 'Danh từ là từ chỉ người, sự vật, hiện tượng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('ec690aa5-78dd-4d13-9ed8-46890426e8eb', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong các phát biểu sau, phát biểu nào đúng?', 'Trong cac phat bieu sau, phat bieu nao dung?', 'Động từ là từ chỉ hoạt động, trạng thái của sự vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
