    ('f52ab83c-db54-4279-87ce-c08c66f507bf', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Quê hương thường được miêu tả gắn với cánh đồng, dòng sông, lũy tre. Theo em, nhận định trên đúng hay sai?', 'Que huong thuong duoc mieu ta gan voi canh dong, dong song, luy tre. Theo em, nhan dinh tren dung hay sai?', 'Quê hương thường được miêu tả gắn với cánh đồng, dòng sông, lũy tre.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('2eadb4cb-3bc6-4546-bfc0-5aa2f52a9908', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phương án nào dưới đây là đúng?', 'Phuong an nao duoi day la dung?', 'Kể chuyện cần có nhân vật, sự việc và diễn biến rõ ràng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('41e0d099-212d-4937-a281-cb8b7b82b86c', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc. Câu trên đúng hay sai?', 'Tu ''xanh biec'' la mot tinh tu mieu ta mau sac. Cau tren dung hay sai?', 'Từ ''xanh biếc'' là một tính từ miêu tả màu sắc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('9bd155a6-f4fa-4b3f-bf8c-91c25ac6956f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ý nào sau đây phản ánh đúng nội dung đã học?', 'Y nao sau day phan anh dung noi dung da hoc?', 'Dấu hai chấm thường dùng để báo hiệu lời giải thích hoặc liệt kê.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('e698e12e-6ee0-48c5-b15e-de63a0b36934', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Danh từ là từ chỉ người, sự vật, hiện tượng. Theo em, nhận định trên đúng hay sai?', 'Danh tu la tu chi nguoi, su vat, hien tuong. Theo em, nhan dinh tren dung hay sai?', 'Danh từ là từ chỉ người, sự vật, hiện tượng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('24e97413-4d1a-433d-a456-027edd931f0d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Xác định phát biểu đúng trong số các phương án sau:', 'Xac dinh phat bieu dung trong so cac phuong an sau:', 'Động từ là từ chỉ hoạt động, trạng thái của sự vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('9403b7bb-67b5-4867-9020-457b83013e20', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Tính từ là từ chỉ đặc điểm, tính chất của sự vật. Câu trên đúng hay sai?', 'Tinh tu la tu chi dac diem, tinh chat cua su vat. Cau tren dung hay sai?', 'Tính từ là từ chỉ đặc điểm, tính chất của sự vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('926b9f54-08ec-4e32-bb29-9708f4fb90fc', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 3 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu nào sau đây nêu đúng kiến thức đã học?', 'Cau nao sau day neu dung kien thuc da hoc?', 'So sánh là đối chiếu hai sự vật có nét tương đồng, ví dụ ''hiền như bụt''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 3']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
